namespace ghidra.app.plugin.core.compositeeditor;






using docking;
using docking.widgets;
using docking.widgets.table;
using generic.theme;
using ghidra.app.context;
using ghidra.app.services;
using ghidra.app.util.datatype;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util;
